		t.Fatal(err)
	}
	receiptWire := envelopeWire(t, receiptEnvelope)
	if peer {
		state.PeerReceiptRecord = &bootstrap.StoredRecord{Bytes: receiptWire, SHA256: digest(receiptWire)}
	} else {
		state.SeedReceiptRecord = &bootstrap.StoredRecord{Bytes: receiptWire, SHA256: digest(receiptWire)}
	}
	markerDirectory := filepath.Join(t.TempDir(), "marker")
	if err := os.Mkdir(markerDirectory, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(markerDirectory, 0o755); err != nil {
		t.Fatal(err)
	}
	prepared := admissionPreparedIdentity(t, "controller-b")
	trustStore := admissionTrustStore(t, roots)
	writeAdmissionLaunchInputs(t, trustStore, manifest)
	ledger := &countingLedgerOpener{state: state}
	material := &countingMaterialChecker{}
	credentials := &countingCredentialChecker{}
	gate := Gate{Roots: roots, AnchorWire: anchorWire, Expected: bootstrap.BootstrapAnchorExpectation{
		DeploymentID: anchored.DeploymentID, Environment: anchored.Environment, Cell: anchored.Cell},
		LoadedControllerConfigSHA256: manifest.ControllerConfigSHA256,
		Descriptor:                   fixedDescriptor{slot: "controller-b", instance: instanceID}, Instances: fakeInstanceObserver{observation},
		Ledgers: ledger, Binary: fixedBinaryChecker{}, Material: material, Credentials: credentials,
		ObserveIdentity: func(AcceptedIdentity) (identityrekey.BrokerIdentity, identityrekey.StoreIdentity, error) {
			return prepared.Broker, prepared.Store, nil
		},
		InitialIdentity: func(bootstrap.Manifest) (identityrekey.BrokerIdentity, identityrekey.StoreIdentity, error) {
			return prepared.Broker, prepared.Store, nil
		},
		trustStore:          &trustStore,
		Markers:             MarkerStore{directory: markerDirectory, ownerUID: uint32(os.Getuid()), allowUnsafeAncestors: true},
		ClockCheck:          func() error { return nil },
		Now:                 func() time.Time { return now },
		InitialFounderFloor: func(context.Context, AcceptedInstall, time.Time) error { return nil },
		InitialPeerFloor: func(context.Context, AcceptedInstall, bootstrap.SlotState, time.Time) error {
			return nil
		},
	}
	return admissionFlowFixture{gate: gate, ledger: ledger, material: material, credentials: credentials, now: &now,
		rootPrivate: rootPrivate, ledgerPrivate: ledgerPrivate, bakedBinary: bakedBinary}
}

func (opener *countingLedgerOpener) ReadSlot(context.Context, bootstrap.BootstrapScope) (bootstrap.SlotState, error) {
	return opener.state, nil
}

func (opener *countingLedgerOpener) PublishAcceptedInstall(_ context.Context, _ bootstrap.BootstrapScope,
	marker []byte,
) error {
	opener.published = append(opener.published, bytes.Clone(marker))
	if opener.onPublish != nil {
		return opener.onPublish(marker)
	}
	return nil
}

func (opener *countingLedgerOpener) OpenCurrentLedger(_ context.Context, anchor bootstrap.VerifiedBootstrapAnchor,
	_ trust.Keyring,
) (AdmissionLedger, error) {
	if !anchor.IsVerified() {
		return nil, ErrLedgerGrant
	}
	opener.currentCalls++
	if opener.onCurrent != nil {
		opener.onCurrent(opener.currentCalls)
	}
	return opener, nil
}

type fixedBinaryChecker struct{}

func (fixedBinaryChecker) VerifyCurrent(image release.VerifiedImage) (RunningBinary, error) {
	pin := image.Receipt()
	return RunningBinary{SHA256: pin.BinarySHA256, Bytes: pin.BinaryBytes, Architecture: pin.Architecture}, nil
}
func (fixedBinaryChecker) VerifyAccepted(pin identityrekey.BinaryPin) (RunningBinary, error) {
	return RunningBinary{SHA256: pin.SHA256, Bytes: pin.Size, Architecture: pin.Architecture}, nil
}

func (fixedBinaryChecker) VerifySelfUpdated(selfupdate.Layout, trust.Keyring, release.UpdateExpectation,
) (RunningBinary, error) {
	return RunningBinary{}, ErrRunningBinaryMismatch
}

type countingMaterialChecker struct {
	initialCalls, restartCalls int
	onPrepare                  func(CurrentProofVerifier) error
	restartErr                 error
}

func (checker *countingMaterialChecker) PrepareInitial(_ context.Context, _ bootstrap.StartupAuthority,
	_ bootstrap.VerifiedReceipt, _ map[string]string, verifyCurrent CurrentProofVerifier,
) error {
	checker.initialCalls++
	if checker.onPrepare != nil {
		return checker.onPrepare(verifyCurrent)
	}
	return nil
}

func (checker *countingMaterialChecker) RestartPins(accepted AcceptedIdentity, _ trust.Keyring,
) (MaterialPins, error) {
	wire, err := EncodeAcceptedIdentity(accepted)
	if err != nil {
		return MaterialPins{}, err
	}
	pins := ManifestPins(acceptedMaterialDigests(accepted))
	pins.acceptance, err = accepted.AcceptanceSHA256()
	if err != nil {
		return MaterialPins{}, err
	}
	pins.slot = accepted.Slot
	pins.acceptedSHA256 = digest(wire)
	pins.references = accepted.MaterialReferences
	return pins, nil
}

func (checker *countingMaterialChecker) VerifyRestart(context.Context, AcceptedIdentity,
	MaterialPins,
) error {
	checker.restartCalls++
	return checker.restartErr
}

type countingCredentialChecker struct {
	calls    int
	err      error
	onVerify func()
}

type stagedSecretMaterializer struct {
	calls int
}

func (materializer *stagedSecretMaterializer) MaterializeCurrent(_ context.Context, _ bootstrap.StartupAuthority,
	_ bootstrap.VerifiedReceipt, reference bootstrap.SecretReference, directory string, _ func(time.Time) error,
) error {
	materializer.calls++
	content := []byte(reference.TargetFile)
	return os.WriteFile(filepath.Join(directory, reference.TargetFile), content, 0o600)
}

func (checker *countingCredentialChecker) VerifyInitialLiveCredentials(_ context.Context, expected MaterialPins, _ bootstrap.StartupAuthority) error {
	return checker.verify(expected)
}
func (checker *countingCredentialChecker) VerifyLiveCredentials(_ context.Context, expected MaterialPins, _ AcceptedIdentity) error {
	return checker.verify(expected)
}
func (checker *countingCredentialChecker) verify(expected MaterialPins) error {
	checker.calls++
	if checker.onVerify != nil {
		checker.onVerify()
	}
	if len(expected.Digests) == 0 {
		return ErrLiveCredentials
	}
	return checker.err
}

func (gate Gate) AdmitInitial(ctx context.Context) (AcceptedInstall, error) {
	if err := gate.requireInitialJournalAbsent(); err != nil {
		return AcceptedInstall{}, err
	}
	if err := gate.prerequisites(); err != nil {
		return AcceptedInstall{}, err
	}
	now, err := gate.checkedNow()
	if err != nil {
		return AcceptedInstall{}, err
	}
	if _, err := gate.Markers.ReadIdentity(); err == nil || !errors.Is(err, os.ErrNotExist) {
		return AcceptedInstall{}, fmt.Errorf("%w: first install requires an absent marker: %v", ErrAdmission, err)
	}
	prior, priorErr := gate.Markers.ReadInitialFormation()
	if priorErr != nil && !errors.Is(priorErr, os.ErrNotExist) {
		return AcceptedInstall{}, fmt.Errorf("read current initial formation recovery state: %w", priorErr)
	}
	pending, pendingErr := gate.Markers.readInitialExport()
	if pendingErr != nil && !errors.Is(pendingErr, os.ErrNotExist) || pendingErr == nil && priorErr != nil {
		return AcceptedInstall{}, fmt.Errorf("%w: invalid initial export recovery state: %v", ErrAdmission, pendingErr)
	}
	anchorEnvelope, err := proofEnvelope(gate.AnchorWire)
	if err != nil {
		return AcceptedInstall{}, err
	}
	anchor, err := bootstrap.VerifyBootstrapAnchor(anchorEnvelope, gate.Roots, gate.Expected, now, bootstrap.BootstrapAnchorTrustPolicy())
	if err != nil {
		return AcceptedInstall{}, fmt.Errorf("verify current baked anchor: %w", err)
	}
	ctx, stop := context.WithDeadline(ctx, anchor.ExpiresAt())
	defer stop()
	scope, instanceID, err := gate.locate(ctx)
	if err != nil {
		return AcceptedInstall{}, err
	}
	state, ledger, err := gate.currentSlot(ctx, anchor, scope)
	if err != nil {
		return AcceptedInstall{}, err
	}
	observed, err := gate.observe(ctx, instanceID, state, anchor.Anchor())
	if err != nil {
		return AcceptedInstall{}, err
	}
	manifest, receipt, image, err := gate.initialProofs(ctx, state, anchor, observed, now)
	if err != nil {
		return AcceptedInstall{}, err
	}
	payload := manifest.Manifest()
	if !slices.Equal(payload.ControllerSlots, []string{"controller-a", "controller-b", "controller-c"}) ||
		!slices.Contains(payload.ControllerSlots, scope.Slot) || !slices.Contains(payload.ControllerSlots, payload.SeedSlot) {
		return AcceptedInstall{}, fmt.Errorf("%w: fresh installation requires the reviewed controller topology", ErrAdmission)
	}
	// A first install has no adopted generation: the manifest pins the config.
	if manifest.Manifest().ControllerConfigSHA256 != gate.LoadedControllerConfigSHA256 {
		return AcceptedInstall{}, fmt.Errorf("%w: loaded controller config differs from signed ledger manifest", ErrAdmission)
	}
	binary, err := gate.binaryChecker().VerifyCurrent(image)
	if err != nil {
		return AcceptedInstall{}, err
	}
	materials := expectedMaterials(manifest.Manifest(), scope.Slot)
	if len(materials) == 0 {
		return AcceptedInstall{}, fmt.Errorf("%w: no controller materials authorized", ErrAdmission)
	}
	receiptRecord := state.SeedReceiptRecord
	if state.Intent.Slot != manifest.Manifest().SeedSlot {
		receiptRecord = state.PeerReceiptRecord
	}
	manifestEnvelope, manifestErr := proofEnvelope(state.ManifestRecord.Bytes)
	receiptEnvelope, receiptErr := proofEnvelope(receiptRecord.Bytes)
	if manifestErr != nil || receiptErr != nil {
		return AcceptedInstall{}, ErrAdmission
	}
	marker := AcceptedInstall{
		SchemaVersion: 1, AnchorSHA256: anchor.Digest(), ManifestSHA256: state.ManifestRecord.SHA256,
		ReceiptSHA256: receiptRecord.SHA256, ImageReceiptSHA256: digest(manifest.Manifest().ReleaseImageReceiptWire),
		DeploymentID: scope.DeploymentID, Cell: scope.Cell, Slot: scope.Slot,
		SeedSlot:  manifest.Manifest().SeedSlot,
		ImageOCID: state.Intent.ImageOCID, InstanceOCID: instanceID,
		PrimaryVNICOCID: observed.PrimaryVNICOCID, PrimaryPrivateIP: observed.PrimaryPrivateIP,
		HeadAttempt: state.Head.Attempt, HeadGeneration: state.Head.Generation,
		ResultSHA256: state.ResultRecord.SHA256, BinarySHA256: binary.SHA256,
		MaterialSHA256: materials, AcceptedAt: now,
		ManagedMaterial: manifest.Manifest().ManagedMaterial,
	}
	if priorErr == nil {
		marker.AcceptedAt = prior.AcceptedAt
		if !sameInitialFormation(marker, prior) ||
			!coveredAt(anchor.IssuedAt(), anchor.ExpiresAt(), prior.AcceptedAt) ||
			!coveredAt(manifestEnvelope.IssuedAt, manifestEnvelope.ExpiresAt, prior.AcceptedAt) ||
			!coveredAt(image.IssuedAt(), image.ExpiresAt(), prior.AcceptedAt) ||
			!coveredAt(receiptEnvelope.IssuedAt, receiptEnvelope.ExpiresAt, prior.AcceptedAt) {
			return AcceptedInstall{}, fmt.Errorf("%w: initial formation recovery differs from verified current installation", ErrAdmission)
		}
	}
	launchStore := bakedStore{directory: BakedDirectory}
	if gate.trustStore != nil {
		launchStore = *gate.trustStore
	}
	launchPins, err := launchStore.measureInitialLaunchMaterial(manifest, gate.Roots, now)
	if err != nil {
		return AcceptedInstall{}, fmt.Errorf("measure current public host launch inputs: %w", err)
	}
	verifyCurrent := func(_ time.Time) error {
		if err := ctx.Err(); err != nil {
			return err
		}
		if err := gate.requireInitialJournalAbsent(); err != nil {
			return err
		}
		at, err := gate.checkedNow()
		if err != nil {
			return err
		}
		currentAnchor, err := bootstrap.VerifyBootstrapAnchor(anchorEnvelope, gate.Roots, gate.Expected,
			at, bootstrap.BootstrapAnchorTrustPolicy())
		if err != nil || currentAnchor.Digest() != anchor.Digest() {
			return fmt.Errorf("%w: current baked anchor or ledger grant expired: %v", ErrAdmission, err)
		}
		_, _, _, err = gate.initialProofs(ctx, state, currentAnchor, observed, at)
		if err != nil {
			return fmt.Errorf("%w: current manifest, image, or instance receipt expired: %v", ErrAdmission, err)
		}
		currentPins, err := launchStore.measureInitialLaunchMaterial(manifest, gate.Roots, at)
		if err != nil || !maps.Equal(launchPins, currentPins) {
			return fmt.Errorf("%w: current public host launch inputs changed or expired: %v", ErrAdmission, err)
		}
		return nil
	}
	if err := verifyCurrent(time.Time{}); err != nil {
		return AcceptedInstall{}, err
	}
	if pendingErr == nil {
		if pending.AcceptedAt.After(now) {
			return AcceptedInstall{}, ErrAdmission
		}
		rebuilt, err := AcceptedIdentityFromInitial(InitialAcceptedIdentityInputs{
			OperationID: entityid.Derive("accepted-install", manifest.Digest(), receiptRecord.SHA256),
			Manifest:    manifest, Receipt: receipt, Image: image, Observed: observed, Binary: binary,
			Broker: pending.Broker, Store: pending.Store, LaunchMaterialSHA256: launchPins,
			AcceptedAt: pending.AcceptedAt, VerifyCurrent: verifyCurrent,
		})
		if err != nil {
			return AcceptedInstall{}, err
		}
		if err := sameInitialExport(pending, rebuilt); err != nil {
			return AcceptedInstall{}, err
		}
		if err := verifyAcceptedStoreFiles(pending.Store); err != nil {
			return AcceptedInstall{}, err
		}
	}
	if err := gate.Material.PrepareInitial(ctx, manifest, receipt, materials, verifyCurrent); err != nil {
		return AcceptedInstall{}, fmt.Errorf("prepare current controller materials: %w", err)
	}
	if pendingErr == nil {
		if err := VerifyAcceptedLocalIdentity(pending, gate.ObserveIdentity); err != nil {
			return AcceptedInstall{}, err
		}
	}
	if err := gate.Credentials.VerifyInitialLiveCredentials(ctx, ManifestPins(materials), manifest); err != nil {
		return AcceptedInstall{}, fmt.Errorf("verify live controller credentials: %w", err)
	}
	acceptedAt, err := gate.checkedNow()
	if err != nil {
		return AcceptedInstall{}, err
	}
	if !coveredAt(anchor.IssuedAt(), anchor.ExpiresAt(), acceptedAt) ||
		!coveredAt(manifestEnvelope.IssuedAt, manifestEnvelope.ExpiresAt, acceptedAt) ||
		!coveredAt(image.IssuedAt(), image.ExpiresAt(), acceptedAt) ||
		!coveredAt(receiptEnvelope.IssuedAt, receiptEnvelope.ExpiresAt, acceptedAt) {
		return AcceptedInstall{}, fmt.Errorf("%w: signed proofs do not cover final acceptance time", ErrAdmission)
	}
	if err := ctx.Err(); err != nil {
		return AcceptedInstall{}, fmt.Errorf("%w: initial admission ended before acceptance: %w", ErrAdmission, err)
	}
	if priorErr != nil {
		marker.AcceptedAt = acceptedAt
	}

	if err := verifyCurrent(time.Time{}); err != nil {
		return AcceptedInstall{}, err
	}
	if state.Intent.Slot == manifest.Manifest().SeedSlot {
		if gate.InitialFounderFloor == nil {
			return AcceptedInstall{}, fmt.Errorf("%w: initial seed founder floor provisioner is absent", ErrAdmission)
		}
		if state.Intent.Mode != bootstrap.IntentModeExternalSeed || state.Head.Attempt != 1 ||
			state.Head.Generation != 1 {
			return AcceptedInstall{}, fmt.Errorf("%w: seed floor requires the first external-seed attempt", ErrAdmission)
		}
		if err := gate.InitialFounderFloor(ctx, marker, acceptedAt); err != nil {
			return AcceptedInstall{}, fmt.Errorf("%w: provision initial seed founder floor: %v", ErrAdmission, err)
		}
	} else if state.Intent.Mode == bootstrap.IntentModeManaged {
		if gate.InitialPeerFloor == nil {
			return AcceptedInstall{}, fmt.Errorf("%w: initial managed peer floor provisioner is absent", ErrAdmission)
		}
		if err := gate.InitialPeerFloor(ctx, marker, state, acceptedAt); err != nil {
			return AcceptedInstall{}, fmt.Errorf("%w: provision initial peer founder floor: %v", ErrAdmission, err)
		}
	}
	if err := verifyCurrent(time.Time{}); err != nil {
		return AcceptedInstall{}, err
	}
	finalAt, err := gate.checkedNow()
	if err != nil {
		return AcceptedInstall{}, err
	}
	if !coveredAt(anchor.IssuedAt(), anchor.ExpiresAt(), finalAt) ||
		!coveredAt(manifestEnvelope.IssuedAt, manifestEnvelope.ExpiresAt, finalAt) ||
		!coveredAt(image.IssuedAt(), image.ExpiresAt(), finalAt) ||
		!coveredAt(receiptEnvelope.IssuedAt, receiptEnvelope.ExpiresAt, finalAt) {
		return AcceptedInstall{}, fmt.Errorf("%w: signed proofs do not cover final marker publication time", ErrAdmission)
	}
	if err := ctx.Err(); err != nil {
		return AcceptedInstall{}, fmt.Errorf("%w: initial admission ended before marker publication: %w", ErrAdmission, err)
	}
	if err := verifyCurrent(finalAt); err != nil {
		return AcceptedInstall{}, err
	}
	broker, store, err := gate.InitialIdentity(manifest.Manifest())
	if err != nil {
		return AcceptedInstall{}, fmt.Errorf("prepare fresh installation identity: %w", err)
	}
	finalAt, err = gate.checkedNow()
	if err != nil {
		return AcceptedInstall{}, err
	}
	if priorErr != nil {
		marker.AcceptedAt = finalAt
	}
	acceptanceAt := finalAt
	if pendingErr == nil {
		if pending.AcceptedAt.After(finalAt) || !coveredAt(anchor.IssuedAt(), anchor.ExpiresAt(), pending.AcceptedAt) ||
			!coveredAt(manifestEnvelope.IssuedAt, manifestEnvelope.ExpiresAt, pending.AcceptedAt) ||
			!coveredAt(image.IssuedAt(), image.ExpiresAt(), pending.AcceptedAt) ||
			!coveredAt(receiptEnvelope.IssuedAt, receiptEnvelope.ExpiresAt, pending.AcceptedAt) {
			return AcceptedInstall{}, fmt.Errorf("%w: pending export acceptance is outside current proofs", ErrAdmission)
		}
		acceptanceAt = pending.AcceptedAt
	}
	accepted, err := AcceptedIdentityFromInitial(InitialAcceptedIdentityInputs{
		OperationID: entityid.Derive("accepted-install", manifest.Digest(), receiptRecord.SHA256),
		Manifest:    manifest, Receipt: receipt, Image: image, Observed: observed, Binary: binary,
		Broker: broker, Store: store, LaunchMaterialSHA256: launchPins,
		AcceptedAt: acceptanceAt, VerifyCurrent: verifyCurrent,
	})
	if err != nil {
		return AcceptedInstall{}, fmt.Errorf("normalize fresh accepted installation: %w", err)
	}
	if pendingErr == nil {
		if err := sameInitialExport(pending, accepted); err != nil {
			return AcceptedInstall{}, fmt.Errorf("%w: current installation differs from pending export: %w", ErrAdmission, err)
		}
	}
	if err := gate.requireInitialJournalAbsent(); err != nil {
		return AcceptedInstall{}, err
	}
	if err := gate.publishInitialFormation(marker); err != nil {
		return AcceptedInstall{}, err
	}
	if err := verifyCurrent(finalAt); err != nil {
		return AcceptedInstall{}, err
	}
	if err := gate.Markers.stageInitialExport(accepted, gate.ObserveIdentity); err != nil {
		return AcceptedInstall{}, fmt.Errorf("stage accepted-install export: %w", err)
	}
	if err := publishAcceptedInstall(ctx, ledger, scope, accepted); err != nil {
		return AcceptedInstall{}, err
	}
	if err := verifyCurrent(time.Time{}); err != nil {
		return AcceptedInstall{}, err
	}
	if err := gate.Markers.WriteNewIdentity(accepted, gate.ObserveIdentity); err != nil {
		return AcceptedInstall{}, fmt.Errorf("persist accepted-install marker: %w", err)
	}
	if err := gate.Markers.clearInitialExport(); err != nil {
		return AcceptedInstall{}, fmt.Errorf("clear completed initial export: %w", err)
	}
	return marker, nil
}

func (store bakedStore) readLaunchFiles(names []string) (map[string][]byte, error) {
	dir, err := store.openDirectory(store.directory)
	if err != nil {
		return nil, err
	}
	defer unix.Close(dir)
	wires := make(map[string][]byte, len(names))
	for _, name := range names {
		maximum := int64(trust.MaxEnvelopeBytes)
		switch name {
		case HostEnrollmentFilename:
			maximum = hostenroll.MaxPublicBundleBytes
		case OperatorSSHKeyFilename:
			maximum = maxOperatorSSHKey
		case ManagedHostImageReceiptFilename, ManagedHostImageDelegationFilename:
		default:
			return nil, ErrLaunchMaterial
		}
		wire, err := store.readFile(dir, name, maximum)
		if err != nil {
			return nil, fmt.Errorf("read root-owned public launch input %s: %w", name, err)
		}
		wires[name] = wire
	}
	return wires, nil
}

func validateHostLaunchInputs(enrollment, ssh []byte, cell, environment string) error {
	bundle, err := hostenroll.ParsePublicBundle(enrollment)
	if err != nil {
		return err
	}
	if err := bundle.MatchesImageLayout(); err != nil {
		return err
	}
	if bundle.Cell != strings.ToLower(cell) || bundle.Region != cell || bundle.Environment != environment {
		return ErrLaunchMaterial
	}
	return validateOperatorSSHKey(ssh)
}

func (store bakedStore) measureInitialLaunchMaterial(manifest bootstrap.StartupAuthority, roots trust.Keyring, now time.Time) (map[string]string, error) {
	if manifest.Digest() == "" {
		return nil, ErrLaunchMaterial
	}
	payload := manifest.Manifest()
	var regionWire []byte
	for _, file := range payload.ControllerFiles {
		if file.Name == "oci-region.json" {
			if digest(file.Bytes) != file.SHA256 {
				return nil, ErrLaunchMaterial
			}
			regionWire = file.Bytes
		}
	}
	expected, err := managedLaunchExpectation(regionWire, string(payload.Cell), payload.Environment)
	if err != nil {
		return nil, err
	}
	wires, err := store.readLaunchFiles(acceptedLaunchNames[:])
	if err != nil {
		return nil, err
	}
	if err := validateHostLaunchInputs(wires[HostEnrollmentFilename], wires[OperatorSSHKeyFilename], string(payload.Cell), payload.Environment); err != nil {
		return nil, err
	}
	if _, err := release.VerifyImageCurrent(wires[ManagedHostImageReceiptFilename], wires[ManagedHostImageDelegationFilename], roots,
		expected, now); err != nil {
		return nil, err
	}
	pins := make(map[string]string, len(wires))
	for name, wire := range wires {
		pins[name] = digest(wire)
	}
	return pins, nil
}

func managedLaunchExpectation(regionWire []byte, cell, environment string) (release.ImageExpectation, error) {
	region, err := oci.ParseRegionConfig(regionWire)
	if err != nil || string(region.Region) != cell {
		return release.ImageExpectation{}, ErrLaunchMaterial
	}
	// Offline installation checks the signed image identity; launch observes its processor through OCI.
	return release.ImageExpectation{Environment: environment, LogicalRegion: cell, OCIImageOCID: region.ImageID}, nil
}

func (store bakedStore) openDirectory(path string) (int, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return -1, ErrBakedInputs
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	for _, component := range strings.Split(strings.TrimPrefix(path, "/"), "/") {
		if component == "" || component == "." || component == ".." {
			unix.Close(fd)
			return -1, ErrBakedInputs
		}
		next, err := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
		unix.Close(fd)
		if err != nil {
			return -1, err
		}
		fd = next
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil ||
			!store.allowUnsafeAncestors && (stat.Uid != 0 || stat.Gid != 0 || stat.Mode&0o777 != 0o755) {
			unix.Close(fd)
			return -1, ErrBakedInputs
		}
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil ||
		stat.Uid != store.ownerUID || stat.Gid != store.ownerGID || stat.Mode&0o777 != 0o755 {
		unix.Close(fd)
		return -1, ErrBakedInputs
	}
	return fd, nil
}

func (store bakedStore) readFile(dir int, name string, maximum int64) ([]byte, error) {
	if strings.Contains(name, "/") || name == "" || maximum <= 0 {
		return nil, ErrBakedInputs
	}
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != store.ownerUID || stat.Gid != store.ownerGID ||
		stat.Mode&0o7777 != 0o444 || stat.Nlink != 1 || stat.Size <= 0 || stat.Size > maximum {
		return nil, ErrBakedInputs
	}
	wire, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil || len(wire) == 0 || int64(len(wire)) > maximum {
		return nil, ErrBakedInputs
	}
	return wire, nil
}

func (store MarkerStore) ReadIdentity() (AcceptedIdentity, error) {
	dir, err := store.openDirectory()
	if err != nil {
		return AcceptedIdentity{}, err
	}
	defer unix.Close(dir)
	wire, err := store.readIdentityBytes(dir, markerName)
	if err != nil {
		return AcceptedIdentity{}, err
	}
	return DecodeAcceptedIdentity(wire)
}

func (store MarkerStore) readIdentityBytes(dir int, name string) ([]byte, error) {
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != store.ownerUID || store.ownerUID == 0 && stat.Gid != 0 || stat.Mode&0o7777 != 0o644 ||
		stat.Nlink != 1 || stat.Size <= 0 || stat.Size > MaxAcceptedIdentityBytes {
		return nil, ErrAcceptedIdentity
	}
	wire, err := io.ReadAll(io.LimitReader(file, MaxAcceptedIdentityBytes+1))
	if err != nil || len(wire) == 0 || len(wire) > MaxAcceptedIdentityBytes {
		return nil, ErrAcceptedIdentity
	}
	return wire, nil
}

func (store MarkerStore) WriteNewIdentity(identity AcceptedIdentity, observe IdentityObservation) error {
	return store.publishIdentity(identity.Clone(), "", observe)

func (store MarkerStore) publishIdentity(identity AcceptedIdentity, predecessor string, observe IdentityObservation) error {
	return store.publishIdentityAt(identity, predecessor, observe, markerName)
}

func (store MarkerStore) publishIdentityAt(identity AcceptedIdentity, predecessor string, observe IdentityObservation, name string) error {
	wire, err := EncodeAcceptedIdentity(identity)
	if err != nil {
		return err
	}
	if err := VerifyAcceptedLocalIdentity(identity, observe); err != nil {
		return err
	}
	dir, err := store.openDirectory()
	if err != nil {
		return err
	}
	defer unix.Close(dir)
	lock, err := unix.Openat(dir, ".accepted-identity.lock", unix.O_RDWR|unix.O_CREAT|unix.O_EXCL|unix.O_NOFOLLOW|unix.O_NONBLOCK|unix.O_CLOEXEC, 0o644)
	created := err == nil
	if errors.Is(err, unix.EEXIST) {
		lock, err = unix.Openat(dir, ".accepted-identity.lock", unix.O_RDWR|unix.O_NOFOLLOW|unix.O_NONBLOCK|unix.O_CLOEXEC, 0)
	}
	if err != nil {
		return err
	}
	defer unix.Close(lock)
	var stat unix.Stat_t
	if err := unix.Fstat(lock, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != store.ownerUID || store.ownerUID == 0 && stat.Gid != 0 || stat.Nlink != 1 {
		return ErrAcceptedIdentity
	}
	if created {
		if err := unix.Fchmod(lock, 0o644); err != nil {
			return err
		}
	} else if stat.Mode&0o7777 != 0o644 {
		return ErrAcceptedIdentity
	}
	if err := unix.Flock(lock, unix.LOCK_EX); err != nil {
		return err
	}
	defer unix.Flock(lock, unix.LOCK_UN)
	if predecessor != "" {
		old, err := store.readIdentityBytes(dir, markerName)
		if err != nil {
			return err
		}
		if digest(old) != predecessor {
			return ErrAcceptancePredecessor
		}
	}
	var nonce [12]byte
	if _, err := rand.Read(nonce[:]); err != nil {
		return err
	}
	temporary := ".accepted-install." + hex.EncodeToString(nonce[:])
	fd, err := unix.Openat(dir, temporary, unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0o644)
	if err != nil {
		return err
	}
	defer unix.Unlinkat(dir, temporary, 0)
	file := os.NewFile(uintptr(fd), temporary)
	defer file.Close()
	if err := unix.Fchmod(fd, 0o644); err != nil {
		return err
	}
	if err := unix.Fstat(fd, &stat); err != nil || stat.Uid != store.ownerUID || store.ownerUID == 0 && stat.Gid != 0 ||
		stat.Mode&unix.S_IFMT != unix.S_IFREG || stat.Nlink != 1 {
		return ErrAcceptedIdentity
	}
	if count, err := file.Write(wire); err != nil {
		return err
	} else if count != len(wire) {
		return io.ErrShortWrite
	}
	if err := file.Sync(); err != nil {
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := VerifyAcceptedLocalIdentity(identity, observe); err != nil {
		return err
	}
	if predecessor == "" {
		err = unix.Renameat2(dir, temporary, dir, name, unix.RENAME_NOREPLACE)
	} else {
		old, readErr := store.readIdentityBytes(dir, markerName)
		if readErr != nil {
			return readErr
		}
		if digest(old) != predecessor {
			return ErrAcceptancePredecessor
		}
		err = unix.Renameat(dir, temporary, dir, markerName)
	}
	if err != nil {
		return err
	}
	return unix.Fsync(dir)
}

func (store MarkerStore) ReadInitialFormation() (AcceptedInstall, error) {
	dir, err := store.openDirectory()
	if err != nil {
		return AcceptedInstall{}, err
	}
	defer unix.Close(dir)
	fd, err := unix.Openat(dir, initialFormationName, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return AcceptedInstall{}, fmt.Errorf("open accepted-install marker: %w", err)
	}
	file := os.NewFile(uintptr(fd), initialFormationName)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != store.ownerUID || stat.Gid != 0 && store.ownerUID == 0 ||
		stat.Mode&0o777 != 0o644 || stat.Nlink != 1 || stat.Size <= 0 || stat.Size > maxMarkerBytes {
		return AcceptedInstall{}, ErrInvalidMarker
	}
	data, err := io.ReadAll(io.LimitReader(file, maxMarkerBytes+1))
	if err != nil || len(data) == 0 || len(data) > maxMarkerBytes {
		return AcceptedInstall{}, ErrInvalidMarker
	}
	var marker AcceptedInstall
	if err := protocol.DecodeStrict(data, &marker, maxMarkerBytes); err != nil || marker.validate() != nil {
		return AcceptedInstall{}, ErrInvalidMarker
	}
	canonical, err := protocol.EncodeJSON(marker)
	if err != nil || !bytes.Equal(data, canonical) {
		return AcceptedInstall{}, ErrInvalidMarker
	}
	return marker, nil
}

// WriteNew atomically installs a new marker after the caller has completed all
// current-proof and material checks. It never replaces an accepted marker.
func (store MarkerStore) WriteInitialFormation(marker AcceptedInstall) error {
	if err := marker.validate(); err != nil {
		return err
	}
	data, err := protocol.EncodeJSON(marker)
	if err != nil || len(data) > maxMarkerBytes {
		return ErrInvalidMarker
	}
	dir, err := store.openDirectory()
	if err != nil {
		return err
	}
	defer unix.Close(dir)
	var nonce [12]byte
	if _, err := rand.Read(nonce[:]); err != nil {
		return err
	}
	temporary := ".initial-formation." + hex.EncodeToString(nonce[:])
	fd, err := unix.Openat(dir, temporary, unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0o644)
	if err != nil {
		return fmt.Errorf("create temporary accepted-install marker: %w", err)
	}
	removeTemporary := true
	defer func() {
		if removeTemporary {
			_ = unix.Unlinkat(dir, temporary, 0)
		}
	}()
	file := os.NewFile(uintptr(fd), temporary)
	if err := unix.Fchmod(fd, 0o644); err != nil {
		_ = file.Close()
		return err
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Uid != store.ownerUID ||
		stat.Gid != 0 && store.ownerUID == 0 || stat.Mode&unix.S_IFMT != unix.S_IFREG || stat.Nlink != 1 {
		_ = file.Close()
		return ErrInvalidMarker
	}
	if written, err := file.Write(data); err != nil || written != len(data) {
		_ = file.Close()
		if err != nil {
			return err
		}
		return io.ErrShortWrite
	}
	if err := file.Sync(); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := unix.Renameat2(dir, temporary, dir, initialFormationName, unix.RENAME_NOREPLACE); err != nil {
		return fmt.Errorf("install accepted-install marker without replacement: %w", err)
	}
	removeTemporary = false
	if err := unix.Fsync(dir); err != nil {
		return fmt.Errorf("sync accepted-install marker directory: %w", err)
	}
	return nil
}

func (store MarkerStore) openDirectory() (int, error) {
	if !filepath.IsAbs(store.directory) || filepath.Clean(store.directory) != store.directory {
		return -1, ErrInvalidMarker
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	for _, component := range strings.Split(strings.TrimPrefix(store.directory, "/"), "/") {
		if component == "" || component == "." || component == ".." {
			unix.Close(fd)
			return -1, ErrInvalidMarker
		}
		next, openErr := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
		unix.Close(fd)
		if openErr != nil {
			return -1, fmt.Errorf("open accepted-install directory component: %w", openErr)
		}
		fd = next
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil ||
			!store.allowUnsafeAncestors && (stat.Uid != 0 || stat.Mode&0o022 != 0) {
			unix.Close(fd)
			return -1, ErrInvalidMarker
		}
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Uid != store.ownerUID ||
		stat.Gid != 0 && store.ownerUID == 0 || stat.Mode&0o777 != 0o755 {
		unix.Close(fd)
		return -1, ErrInvalidMarker
	}
	return fd, nil
}

