func currentLedgerConfig(verified bootstrap.VerifiedBootstrapAnchor, roots trust.Keyring) (bootstrap.LedgerConfig, error) {
	if !verified.IsVerified() || len(roots) == 0 {
		return bootstrap.LedgerConfig{}, ErrLedgerGrant
	}
	grant, err := verified.LedgerDelegation()
	if err != nil {
		return bootstrap.LedgerConfig{}, fmt.Errorf("read current anchor ledger grant: %w", err)
	}
	config := ledgerConfigFromAnchor(verified.Anchor(), roots, grant)
	config.AnchorExpiresAt = verified.ExpiresAt()
	return config, nil
}

func (opener InstancePrincipalLedgerOpener) OpenHistoricalLedger(ctx context.Context,
	verified bootstrap.HistoricalBootstrapAnchor, roots trust.Keyring,
) (AdmissionLedger, error) {
	config, err := historicalLedgerConfig(verified, roots)
	if err != nil {
		return nil, err
	}
	return openHistoricalInstancePrincipalLedger(ctx, config, opener.provider)
}

// historicalLedgerConfig is only for historical ReadSlot evidence.
func historicalLedgerConfig(verified bootstrap.HistoricalBootstrapAnchor, roots trust.Keyring) (bootstrap.LedgerConfig, error) {
	if !verified.IsVerified() || len(roots) == 0 {
		return bootstrap.LedgerConfig{}, ErrLedgerGrant
	}
	grant, err := verified.HistoricalLedgerDelegation()
	if err != nil {
		return bootstrap.LedgerConfig{}, fmt.Errorf("read historical anchor ledger evidence: %w", err)
	}
	return ledgerConfigFromAnchor(verified.Anchor(), roots, grant), nil
}

func openHistoricalInstancePrincipalLedger(ctx context.Context, config bootstrap.LedgerConfig,
	provider common.ConfigurationProvider,
) (AdmissionLedger, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	var ledger *bootstrap.Ledger
	var err error
	if provider == nil {
		ledger, err = bootstrap.NewHistoricalInstancePrincipalLedger(config.Cell, config)
	} else {
		ledger, err = bootstrap.NewHistoricalInstancePrincipalLedgerWithProvider(config.Cell, config, provider)
	}
	if err != nil {
		return nil, fmt.Errorf("open historical anchor-scoped OCI bootstrap ledger: %w", err)
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	return admissionLedger{ledger: ledger}, nil
}

// ledgerConfigFromAnchor is called only with a typed verified grant obtained
// from the current or historical anchor accessor. It carries no private root
// signer or unconstrained delegation list.
func ledgerConfigFromAnchor(anchor bootstrap.BootstrapAnchor, roots trust.Keyring,
	grant trust.VerifiedDelegation,
) bootstrap.LedgerConfig {
	domain := anchor.StorageDomain
	return bootstrap.LedgerConfig{
		DeploymentID: anchor.DeploymentID, Environment: anchor.Environment,
		ClusterID: anchor.ClusterID, Cell: anchor.Cell,
		InitialRegionIntentGeneration: anchor.InitialRegionIntentGeneration,
		InitialRegionIntentSHA256:     anchor.InitialRegionIntentSHA256,
		Namespace:                     domain.Namespace, Bucket: domain.LedgerBucket, KMSKeyID: domain.LedgerKMSKeyOCID,
		HeadBucket: domain.HeadBucket, HeadKMSKeyID: domain.HeadKMSKeyOCID, Prefix: domain.Prefix,
		ControllerSlots: slices.Clone(anchor.ControllerSlots),
		TrustRoots:      roots, Delegations: []trust.VerifiedDelegation{grant},
		TrustPolicy: bootstrap.ManifestTrustPolicy(),
	}
}

func NewHistoricalInstancePrincipalLedgerWithProvider(region oci.Region, config LedgerConfig,
	provider common.ConfigurationProvider,
) (*Ledger, error) {
	return newInstancePrincipalLedgerWithProviderMode(region, config, provider, true)
}

func newInstancePrincipalLedgerWithProviderMode(
	region oci.Region,
	config LedgerConfig,
	provider common.ConfigurationProvider,
	historical bool,
) (*Ledger, error) {
	ociRegion, err := validateInstancePrincipalLedgerScope(region, config)
	if err != nil {
		return nil, err
	}
	if provider == nil {
		return nil, errors.New("bootstrap ledger OCI configuration provider is nil")
	}
	providerRegion, err := provider.Region()
	if err != nil {
		return nil, fmt.Errorf("read bootstrap ledger OCI provider region: %w", err)
	}
	if providerRegion != ociRegion {
		return nil, fmt.Errorf("bootstrap ledger OCI provider region %q does not match anchored region %q", providerRegion, ociRegion)
	}
	client, err := objectstorage.NewObjectStorageClientWithConfigurationProvider(provider)
	if err != nil {
		return nil, fmt.Errorf("create OCI Object Storage client for bootstrap ledger: %w", err)
	}
	client.SetRegion(ociRegion)
	client.HTTPClient, err = NewInstancePrincipalSDKHTTPClient()
	if err != nil {
		return nil, fmt.Errorf("configure OCI Object Storage HTTP transport: %w", err)
	}
	if historical {
		return NewHistoricalLedger(&client, config)
	}
	return NewLedger(&client, config)
}

func NewLedger(client ObjectStorageClient, config LedgerConfig) (*Ledger, error) {
	return newLedger(client, config, false)
}

// NewHistoricalLedger constructs an evidence-only reader for the current
// five-domain ledger grant. Its write paths remain
// disabled even if the caller later invokes a mutation method.
func NewHistoricalLedger(client ObjectStorageClient, config LedgerConfig) (*Ledger, error) {
	return newLedger(client, config, true)
}

func newLedger(client ObjectStorageClient, config LedgerConfig, historical bool) (*Ledger, error) {
	if client == nil || validateLedgerAnchor(config) != nil || !ledgerIDPattern.MatchString(config.Namespace) ||
		!ledgerNamePattern.MatchString(config.Bucket) || !strings.HasPrefix(config.KMSKeyID, "ocid1.key.") ||
		len(config.KMSKeyID) > 255 || strings.ContainsAny(config.KMSKeyID, " \t\r\n") || !validLedgerPrefix(config.Prefix) ||
		!ledgerNamePattern.MatchString(config.HeadBucket) || config.HeadBucket == config.Bucket ||
		!strings.HasPrefix(config.HeadKMSKeyID, "ocid1.key.") || len(config.HeadKMSKeyID) > 255 ||
		strings.ContainsAny(config.HeadKMSKeyID, " \t\r\n") ||
		!ledgerIDPattern.MatchString(config.Environment) || config.TrustPolicy.MaxLifetime <= 0 || config.TrustPolicy.ClockSkew < 0 ||
		len(config.ControllerSlots) == 0 || len(config.ControllerSlots) > 64 || hasDuplicate(config.ControllerSlots) ||
		len(config.TrustRoots) == 0 && len(config.Delegations) == 0 || validateLedgerDelegations(config) != nil {
		return nil, errors.New("bootstrap ledger requires separate immutable and coordination buckets, KMS keys, environment, trust policy, and a valid Object Storage client")
	}
	for _, slot := range config.ControllerSlots {
		if !controllerSlotRE.MatchString(slot) {
			return nil, errors.New("bootstrap ledger requires a canonical anchor-pinned controller slot set")
		}
	}
	roots := make(trust.Keyring, len(config.TrustRoots))
	for keyID, key := range config.TrustRoots {
		roots[keyID] = bytes.Clone(key)
	}
	config.TrustRoots = roots
	config.Delegations = slices.Clone(config.Delegations)
	if config.DerivedStartup != nil {
		config.DerivedStartup = new(*config.DerivedStartup)
	}
	config.ControllerSlots = slices.Clone(config.ControllerSlots)
	if config.VerificationNow == nil {
		config.VerificationNow = time.Now
	}
	return &Ledger{client: client, config: config, maxRecord: maxLedgerRecordBytes, readOnly: historical}, nil
}

