func newGenerationInstall(t *testing.T) *generationInstall {
	t.Helper()
	dir := filepath.Join(t.TempDir(), "secrets")
	if err := os.Mkdir(dir, 0o700); err != nil {
		t.Fatal(err)
	}
	install := &generationInstall{t: t, dir: dir}
	install.material = generationtest.New(t, time.Now())
	public, private, _ := ed25519.GenerateKey(rand.Reader)
	install.roots, _ = trust.ParseKeyring(public)
	install.rootKey = private
	install.expected = bootstrap.MaterialGenerationExpectation{DeploymentID: "0000000000YY15F5R431V5JPJ9", Environment: "production",
		ClusterID: "00000000006GRRF84JEVN9TX7M", Cell: "GRU", ControllerSlots: []string{"controller-a", "controller-b", "controller-c"}}
	install.manifest = bootstrap.Manifest{DeploymentID: "0000000000YY15F5R431V5JPJ9", Environment: "production", ClusterID: "00000000006GRRF84JEVN9TX7M",
		Cell: "GRU", Slot: "controller-a", SeedSlot: "controller-b", ControllerSlots: install.expected.ControllerSlots}
	// Manifest-era material: placeholder bytes, except the controller
	// credentials, which renewal re-signs.
	user, _ := nkeys.CreateUser()
	userID, _ := user.PublicKey()
	userSeed, _ := user.Seed()
	claims := jwt.NewUserClaims(userID)
	claims.Expires = time.Now().Add(time.Hour).Unix()
	encoded, _ := claims.Encode(install.material.Cell)
	creds, _ := jwt.FormatUserConfig(encoded, userSeed)
	files := map[string]bootstrap.SecretPurpose{
		"ca.pem": bootstrap.SecretRegionalShared, "operator.jwt": bootstrap.SecretRegionalShared,
		"system.jwt": bootstrap.SecretRegionalShared, "cell.jwt": bootstrap.SecretRegionalShared,
		"system.creds": bootstrap.SecretRegionalShared, "ticket.pub": bootstrap.SecretRegionalShared,
		"ticket.key": bootstrap.SecretRegionalShared, "route-password": bootstrap.SecretRegionalShared, "host-nats-issuer.seed": bootstrap.SecretHostIssuer,
		"host-tls-issuer-key.pem": bootstrap.SecretHostIssuer, "host-tls-issuer-cert.pem": bootstrap.SecretHostIssuer,
		"controller-a.creds": bootstrap.SecretController, "controller-a-tls-cert.pem": bootstrap.SecretController,
		"controller-a-tls-key.pem": bootstrap.SecretController, "controller-a-response.key": bootstrap.SecretController,
	}
	for name, purpose := range files {
		content := []byte("manifest-era " + name)
		if name == "controller-a.creds" {
			content = creds
		}
		install.write(name, content)
		reference := bootstrap.SecretReference{Purpose: purpose, TargetFile: name, SHA256: digest(content), SecretOCID: "ocid1.vaultsecret.oc1.sa-saopaulo-1.baseline-" + strings.ReplaceAll(name, ".", "-"), VersionNumber: 1, MaxBytes: bootstrap.MaxSecretBytes}
		if purpose == bootstrap.SecretController {
			reference.Slot = "controller-a"
		}
		install.manifest.Secrets = append(install.manifest.Secrets, reference)
	}
	path := func(name string) string { return filepath.Join(dir, name) }
	tlsFiles := natscell.TLSFiles{CAFile: path("ca.pem"), CertFile: path("controller-a-tls-cert.pem"),
		KeyFile: path("controller-a-tls-key.pem")}
	install.credential = LiveCredentials{Config: natscell.Config{Cell: "gru", Instance: "controller-a", Replicas: 1,
		CredentialsFile: path("controller-a.creds"), TLS: tlsFiles,
		Embedded: &natscell.Embedded{TLS: tlsFiles, RouteTLS: tlsFiles,
			OperatorJWTFile: path("operator.jwt"), SystemJWTFile: path("system.jwt"), CellJWTFile: path("cell.jwt"),
			SystemCredentialsFile: path("system.creds"), TicketPublicKeyFile: path("ticket.pub")}},
		ServiceUID: uint32(os.Getuid()), ServiceGID: uint32(os.Getgid()),
		ResponseKeyFile: path("controller-a-response.key"), BrokerTicketKeyFile: path("ticket.key"),
		HostNATSIssuerSeedFile: path("host-nats-issuer.seed"), HostTLSIssuerKeyFile: path("host-tls-issuer-key.pem"),
		HostTLSIssuerCertFile: path("host-tls-issuer-cert.pem"), ValidateControllerKeys: func() error { return nil },
		directory: dir, allowUnsafeAncestors: true, ControllerConfig: []byte(oldConfig)}
	install.accepted = acceptedIdentityFixture(t)
	install.accepted.DeploymentID = install.expected.DeploymentID
	install.accepted.ClusterID = install.expected.ClusterID
	install.accepted.Environment = install.expected.Environment
	install.accepted.PrimaryPrivateIP = pinnedIP
	install.accepted.MaterialReferences = install.manifest.Secrets
	install.accepted.Broker = identityrekey.BrokerIdentity{Operator: install.material.OperatorID,
		SystemAccount: install.material.SystemID, CellAccount: install.material.CellID,
		HostSigner: install.material.HostSignerID, RoleSigner: install.material.RoleSignerID}
	install.accepted.ConfigSHA256["controller.json"] = digest([]byte(oldConfig))
	install.accepted.ControllerBindings = []ControllerBinding{install.accepted.localBinding()}
	if err := install.accepted.Validate(); err != nil {
		t.Fatal(err)
	}
	install.configPath = filepath.Join(t.TempDir(), "controller.json")
	if err := os.WriteFile(install.configPath, []byte(oldConfig), 0o644); err != nil {
		t.Fatal(err)
	}
	install.credential.Config.Embedded.RoutePasswordFile = path("route-password")
	return install
}

func (install *generationInstall) write(name string, content []byte) {
	install.t.Helper()
	temporary := filepath.Join(install.dir, "."+name)
	if err := os.WriteFile(temporary, content, 0o600); err != nil {
		install.t.Fatal(err)
	}
	if err := os.Rename(temporary, filepath.Join(install.dir, name)); err != nil {
		install.t.Fatal(err)
	}
}

func (install *generationInstall) read(name string) []byte {
	install.t.Helper()
	content, err := os.ReadFile(filepath.Join(install.dir, name))
	if err != nil {
		install.t.Fatal(err)
	}
	return content
}

func (install *generationInstall) acceptance() string {
	install.t.Helper()
	value, err := install.accepted.AcceptanceSHA256()
	if err != nil {
		install.t.Fatal(err)
	}
	return value
}

func (install *generationInstall) target() GenerationTarget {
	install.t.Helper()
	target, err := generationTarget(install.accepted)
	if err != nil {
		install.t.Fatal(err)
	}
	return target
}

func (install *generationInstall) signedGeneration() ([]byte, map[string][]byte) {
	install.t.Helper()
	envelope, err := bootstrap.SignMaterialGeneration(install.material.Generation(install.expected, 1, ""),
		time.Now().Add(-time.Minute), time.Now().AddDate(0, 6, 0), install.rootKey)
	if err != nil {
		install.t.Fatal(err)
	}
	wire, err := bootstrap.EncodeMaterialGenerationChain([]trust.Envelope{envelope})
	if err != nil {
		install.t.Fatal(err)
	}
	files := map[string][]byte{}
	for name := range bootstrap.MaterialGenerationFiles() {
		files[name] = install.material.Files[name]
	}
	return wire, files
}

func (install *generationInstall) store() MaterialStore {
	return MaterialStore{installedDirectory: install.dir, serviceUID: uint32(os.Getuid()),
		serviceGID: uint32(os.Getgid()), allowUnsafeAncestors: true}
}

// stage writes a stage as a crash would leave it.
func (install *generationInstall) stage(files map[string][]byte) {
	install.t.Helper()
	staging := filepath.Join(install.dir, generationStaging)
	if err := os.Mkdir(staging, 0o700); err != nil && !os.IsExist(err) {
		install.t.Fatal(err)
	}
	for name, content := range files {
		if err := os.WriteFile(filepath.Join(staging, name), content, 0o600); err != nil {
			install.t.Fatal(err)
		}
	}
}

func (install *generationInstall) staged() bool {
	_, err := os.Stat(filepath.Join(install.dir, generationStaging))
	return err == nil
}

func (store MaterialStore) ReadIdentityRekeyMaterial(ctx context.Context, accepted AcceptedIdentity, generationChain []byte, roots trust.Keyring, read SecretReader, now time.Time) (map[string][]byte, error) {
	target, err := generationTarget(accepted)
	if err != nil {
		return nil, err
	}
	var newest *bootstrap.VerifiedMaterialGeneration
	if len(generationChain) != 0 {
		chain, err := bootstrap.DecodeMaterialGenerationChain(generationChain)
		if err != nil {
			return nil, err
		}
		verified, err := target.VerifyChain(chain, roots, now)
		if err != nil {
			return nil, err
		}
		newest = &verified[len(verified)-1]
		if newest.Fingerprint() != accepted.MaterialGenerationSHA256 {
			return nil, fmt.Errorf("%w: proposed chain differs from accepted baseline", ErrMaterial)
		}
	} else if accepted.MaterialGenerationSHA256 != "" {
		return nil, fmt.Errorf("%w: proposed generation chain is missing", ErrMaterial)
	}
	refs := materialReferences(accepted, newest)
	baseline := materialReferences(accepted, nil)
	immutable := acceptedMaterialDigests(accepted)
	delete(immutable, accepted.Slot+"-response.key")
	if newest != nil {
		for _, ref := range newest.Generation().Secrets {
			if ref.Slot == "" || ref.Slot == accepted.Slot {
				if baseline[ref.TargetFile] != ref {
					return nil, fmt.Errorf("%w: proposed generation reference %s differs from accepted baseline", ErrMaterial, ref.TargetFile)
				}
				delete(immutable, ref.TargetFile)
			}
		}
	}
	installed, err := openMaterialDirectory(store.installedDirectory, store.serviceUID, store.serviceGID, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return nil, err
	}
	defer unix.Close(installed)
	if err := store.verifyInstalled(ctx, installed, immutable); err != nil {
		return nil, fmt.Errorf("identity rekey must preserve existing baseline material: %w", err)
	}
	return readReferences(ctx, refs, read)
}

func materialReferences(accepted AcceptedIdentity, newest *bootstrap.VerifiedMaterialGeneration) map[string]bootstrap.SecretReference {
	refs := map[string]bootstrap.SecretReference{}
	for _, reference := range accepted.MaterialReferences {
		refs[reference.TargetFile] = reference
	}
	if newest != nil {
		for _, secret := range newest.Generation().Secrets {
			if secret.Slot == "" || secret.Slot == accepted.Slot {
				refs[secret.TargetFile] = secret
			}
		}
	}
	return refs
}

func readReferences(ctx context.Context, refs map[string]bootstrap.SecretReference, read SecretReader) (map[string][]byte, error) {
	if read == nil && len(refs) != 0 {
		return nil, ErrMaterial
	}
	contents := map[string][]byte{}
	for _, name := range slices.Sorted(maps.Keys(refs)) {
		reference := refs[name]
		if !markerNameRE.MatchString(name) {
			clearContents(contents)
			return nil, ErrMaterial
		}
		content, err := read(ctx, reference)
		if err == nil && (len(content) == 0 || int64(len(content)) > reference.MaxBytes || digest(content) != reference.SHA256) {
			clear(content)
			err = bootstrap.ErrVaultSecretMismatch
		}
		if err != nil {
			clearContents(contents)
			return nil, fmt.Errorf("read %s from Vault: %w", name, err)
		}
		contents[name] = content
	}
	return contents, nil
}

func clearContents(contents map[string][]byte) {
	for _, content := range contents {
		clear(content)
	}
}

func (store MaterialStore) verifyInstalled(ctx context.Context, dir int, expected map[string]string) error {
	for name, want := range expected {
		if err := ctx.Err(); err != nil {
			return err
		}
		content, err := readMaterial(dir, name, store.serviceUID, store.serviceGID, want, bootstrap.MaxSecretBytes)
		if err != nil {
			return fmt.Errorf("verify installed secret %s: %w", name, err)
		}
		clear(content)
	}
	return nil
}

func readMaterial(dir int, name string, uid, gid uint32, want string, maximum int64) ([]byte, error) {
	if !markerNameRE.MatchString(name) || !markerDigestRE.MatchString(want) || maximum <= 0 || maximum > bootstrap.MaxSecretBytes {
		return nil, ErrMaterial
	}
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != 0o600 || stat.Nlink != 1 ||
		stat.Size <= 0 || stat.Size > maximum {
		return nil, ErrMaterial
	}
	content, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil || len(content) == 0 || int64(len(content)) > maximum || digest(content) != want {
		clear(content)
		return nil, ErrMaterial
	}
	return content, nil
}

func openMaterialDirectory(path string, uid, gid uint32, mode uint32, allowUnsafeAncestors bool) (int, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return -1, ErrMaterial
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	components := strings.Split(strings.TrimPrefix(path, "/"), "/")
	for index, component := range components {
		if component == "" || component == "." || component == ".." {
			unix.Close(fd)
			return -1, ErrMaterial
		}
		next, err := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
		unix.Close(fd)
		if err != nil {
			return -1, err
		}
		fd = next
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil ||
			index < len(components)-1 && !allowUnsafeAncestors && (stat.Uid != 0 || stat.Mode&0o022 != 0) {
			unix.Close(fd)
			return -1, ErrMaterial
		}
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != mode {
		unix.Close(fd)
		return -1, ErrMaterial
	}
	return fd, nil
}

func generationTarget(accepted AcceptedIdentity) (GenerationTarget, error) {
	acceptance, err := accepted.AcceptanceSHA256()
	if err != nil {
		return GenerationTarget{}, err
	}
	return GenerationTarget{Slot: accepted.Slot, AcceptanceSHA256: acceptance, Broker: accepted.Broker,
		MaterialGenerationSHA256: accepted.MaterialGenerationSHA256, ControllerConfigSHA256: accepted.ConfigSHA256["controller.json"],
		Expected: bootstrap.MaterialGenerationExpectation{DeploymentID: accepted.DeploymentID,
			Environment: accepted.Environment, ClusterID: accepted.ClusterID, Cell: oci.Region(accepted.Cell),
			ControllerSlots: slices.Clone(accepted.ControllerSlots)}}, nil
}

// VerifyChain admits a new or interrupted generation under the current roots.
func (target GenerationTarget) VerifyChain(chain []trust.Envelope, roots trust.Keyring, now time.Time) ([]bootstrap.VerifiedMaterialGeneration, error) {
	verified, err := bootstrap.VerifyMaterialGenerationChain(chain, roots, target.Expected, now)
	if err != nil {
		return nil, err
	}
	return target.bindChain(verified)
}

// VerifyAdoptedChain verifies a previously installed chain's signatures and acceptance.
func (target GenerationTarget) VerifyAdoptedChain(chain []trust.Envelope, roots trust.Keyring) ([]bootstrap.VerifiedMaterialGeneration, error) {
	verified, err := bootstrap.VerifyAdoptedMaterialGenerationChain(chain, roots, target.Expected)
	if err != nil {
		return nil, err
	}
	return target.bindChain(verified)
}

func (target GenerationTarget) bindChain(verified []bootstrap.VerifiedMaterialGeneration) ([]bootstrap.VerifiedMaterialGeneration, error) {
	if !slices.Contains(target.Expected.ControllerSlots, target.Slot) || !markerDigestRE.MatchString(target.AcceptanceSHA256) ||
		validateAcceptedBroker(target.Broker) != nil || len(verified) == 0 {
		return nil, ErrMaterial
	}
	baseline := target.MaterialGenerationSHA256 == ""
	for _, item := range verified {
		generation := item.Generation()
		if generation.Operator != target.Broker.Operator || generation.SystemAccount != target.Broker.SystemAccount ||
			generation.CellAccount != target.Broker.CellAccount || generation.HostSigner != target.Broker.HostSigner ||
			generation.RoleSigner != target.Broker.RoleSigner {
			return nil, fmt.Errorf("%w: generation changes the accepted broker identity", ErrMaterial)
		}
		if item.Fingerprint() == target.MaterialGenerationSHA256 {
			baseline = true
			if generation.AccountSigner != target.Broker.AccountSigner {
				return nil, fmt.Errorf("%w: accepted generation changes the account signer", ErrMaterial)
			}
		}
	}
	if !baseline {
		return nil, fmt.Errorf("%w: chain omits the accepted material generation", ErrMaterial)
	}
	for _, pin := range verified[len(verified)-1].Generation().ControllerConfigs {
		if pin.Slot == target.Slot && pin.AcceptanceSHA256 != target.AcceptanceSHA256 {
			return nil, fmt.Errorf("%w: generation config is bound to another acceptance", ErrMaterial)
		}
	}
	return verified, nil
}

// VerifyFiles checks every local file and config, plus their material semantics.
func (target GenerationTarget) VerifyFiles(generation bootstrap.MaterialGeneration, read func(string) ([]byte, error), now time.Time) error {
	for _, secret := range generation.Secrets {
		if secret.Slot == "" || secret.Slot == target.Slot {
			if _, err := read(secret.TargetFile); err != nil {
				return err
			}
		}
	}
	for _, pin := range generation.ControllerConfigs {
		if pin.Slot == target.Slot {
			if pin.AcceptanceSHA256 != target.AcceptanceSHA256 {
				return fmt.Errorf("%w: controller config is bound to another acceptance", ErrMaterial)
			}
			if _, err := read(GenerationConfigFile(target.Slot)); err != nil {
				return err
			}
		}
	}
	if _, err := bootstrapmaterial.CheckGenerationFiles(generation, read, now); err != nil {
		return err
	}
	if target.Broker.InterRegionAccount != "" {
		wire, err := read("interregion.jwt")
		if err != nil {
			return err
		}
		claim, err := jwt.DecodeAccountClaims(strings.TrimSpace(string(wire)))
		if err != nil || claim.Subject != target.Broker.InterRegionAccount {
			return fmt.Errorf("%w: interregion account differs from accepted broker", ErrMaterial)
		}
	}
	return nil
}

