func (install *generationInstall) write(name string, content []byte) {
	install.t.Helper()
	temporary := filepath.Join(install.dir, "."+name)
	if err := os.WriteFile(temporary, content, 0o600); err != nil {
		install.t.Fatal(err)
	}
	if err := os.Rename(temporary, filepath.Join(install.dir, name)); err != nil {
		install.t.Fatal(err)
	}
}

func (install *generationInstall) read(name string) []byte {
	install.t.Helper()
	content, err := os.ReadFile(filepath.Join(install.dir, name))
	if err != nil {
		install.t.Fatal(err)
	}
	return content
}

func (install *generationInstall) acceptance() string {
	install.t.Helper()
	value, err := install.accepted.AcceptanceSHA256()
	if err != nil {
		install.t.Fatal(err)
	}
	return value
}

func (install *generationInstall) target() GenerationTarget {
	install.t.Helper()
	target, err := generationTarget(install.accepted)
	if err != nil {
		install.t.Fatal(err)
	}
	return target
}

func (installer generationInstaller) restoreDisk(ctx context.Context, accepted AcceptedIdentity, read SecretReader, removeDiskCopies bool, now time.Time) (string, error) {
	started := time.Now()
	store := installer.store
	dir, err := openMaterialDirectory(store.installedDirectory, store.serviceUID, store.serviceGID, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return "", err
	}
	defer unix.Close(dir)
	if memoryFilesystem(dir) {
		return "", fmt.Errorf("%w: credential directory is already in memory", ErrMaterial)
	}
	staging, err := store.openStaging(dir)
	if err == nil {
		unix.Close(staging)
		return "", fmt.Errorf("%w: refuse to hide an existing disk-backed material stage", ErrMaterial)
	}
	if !errors.Is(err, os.ErrNotExist) {
		return "", err
	}
	held, err := installer.heldGenerations()
	if err != nil {
		return "", err
	}
	wire, chain, staged, config, _ := installer.armedStage(held, now)
	defer clearContents(staged)
	successor := wire != nil
	if !successor {
		chain = held
		if len(chain) != 0 {
			wire, err = bootstrap.EncodeMaterialGenerationChain(chain)
			if err != nil {
				return "", err
			}
		}
	}
	var newest *bootstrap.VerifiedMaterialGeneration
	if len(chain) != 0 {
		verified, err := installer.target.VerifyAdoptedChain(chain, installer.historicalRoots)
		if err != nil {
			return "", err
		}
		newest = &verified[len(verified)-1]
		if !now.Before(newest.ExpiresAt()) {
			return "", fmt.Errorf("%w: adopted material generation expired", ErrMaterial)
		}
	} else if installer.target.MaterialGenerationSHA256 != "" {
		return "", fmt.Errorf("%w: accepted material generation is missing", ErrMaterial)
	}
	refs := materialReferences(accepted, newest)
	contents, err := readReferences(ctx, refs, read)
	if err != nil {
		return "", err
	}
	defer clearContents(contents)
	var diskContents map[string][]byte
	var diskChain []byte
	if removeDiskCopies {
		diskRefs, wire, err := installer.diskRemovalPlan(dir, accepted, held)
		if err != nil {
			return "", err
		}
		diskChain = wire
		diskContents, err = readReferences(ctx, diskRefs, read)
		if err != nil {
			return "", err
		}
		defer clearContents(diskContents)
		if _, err := store.checkRestore(ctx, diskRefs, diskChain, func(_ context.Context, ref bootstrap.SecretReference) ([]byte, error) {
			return bytes.Clone(diskContents[ref.TargetFile]), nil
		}); err != nil {
			return "", err
		}
	}
	if successor {
		checked := maps.Clone(contents)
		if config != nil {
			checked[GenerationConfigFile(installer.target.Slot)] = config
		}
		if _, err := installer.target.VerifyChain(chain, installer.roots, now.Add(time.Since(started))); err != nil {
			return "", err
		}
		if err := installer.target.VerifyFiles(newest.Generation(), materialReader(checked), now.Add(time.Since(started))); err != nil {
			return "", err
		}
		if err := installer.preserveConfig(held); err != nil {
			return "", err
		}
		if config != nil {
			if err := writeSynced(filepath.Join(filepath.Dir(installer.config), pendingControllerConfig), config); err != nil {
				return "", err
			}
		}
	}
	if err := verifyRestoreContents(installer.target, installer.historicalRoots, wire, contents, installer.config, now.Add(time.Since(started))); err != nil {
		return "", err
	}
	if wire != nil {
		if err := writeSynced(store.chainCopy, wire); err != nil {
			return "", err
		}
		if err := convergeRestoredConfig(store, installer.target, installer.historicalRoots, wire, installer.config, now.Add(time.Since(started)), contents); err != nil {
			return "", err
		}
	}
	removed := 0
	if removeDiskCopies {
		if removed, err = store.removeDiskCopies(diskContents, diskChain); err != nil {
			return "", err
		}
	}
	if err := mountMemory(store.installedDirectory, store.serviceUID, store.serviceGID); err != nil {
		return "", fmt.Errorf("mount the credential directory in memory: %w", err)
	}
	if err := verifyRestoreContents(installer.target, installer.historicalRoots, wire, contents, installer.config, now.Add(time.Since(started))); err != nil {
		return "", err
	}
	if err := store.fill(contents, wire); err != nil {
		return "", err
	}
	return fmt.Sprintf("restored %d files from Vault into memory; removed %d disk copies", len(refs), removed), nil
}

// Disk cleanup uses the exact installed prefix, even after a successor's durable commit.
func (installer generationInstaller) diskRemovalPlan(dir int, accepted AcceptedIdentity, held []trust.Envelope) (map[string]bootstrap.SecretReference, []byte, error) {
	wire, err := readUnpinned(dir, MaterialGenerationsFile, installer.store.serviceUID, installer.store.serviceGID, maxGenerationChainBytes)
	var newest *bootstrap.VerifiedMaterialGeneration
	if err == nil {
		chain, err := bootstrap.DecodeMaterialGenerationChain(wire)
		if err != nil {
			return nil, nil, err
		}
		if !chainIs(held, wire) && !bootstrap.ExtendsMaterialGenerationChain(held, chain) {
			return nil, nil, fmt.Errorf("%w: disk cleanup chain differs from held chain", ErrMaterial)
		}
		verified, err := installer.target.VerifyAdoptedChain(chain, installer.historicalRoots)
		if err != nil {
			return nil, nil, err
		}
		newest = &verified[len(verified)-1]
	} else if !errors.Is(err, os.ErrNotExist) {
		return nil, nil, err
	}
	refs := materialReferences(accepted, newest)
	names, err := stagedNames(dir)
	if err != nil {
		return nil, nil, err
	}
	present := map[string]bootstrap.SecretReference{}
	for _, name := range names {
		if name == MaterialGenerationsFile && wire != nil {
			continue
		}
		ref, ok := refs[name]
		if !ok {
			return nil, nil, fmt.Errorf("%w: %s has no verified disk reference", ErrMaterial, name)
		}
		present[name] = ref
	}
	return present, wire, nil
}

func (installer generationInstaller) heldGenerations() ([]trust.Envelope, error) {
	held, err := installer.store.installedGenerations()
	if err != nil {
		return nil, fmt.Errorf("read installed generations: %w", err)
	}
	// A reboot can empty the credential directory, never the durable rollback floor.
	durableWire, err := readBoundedFile(installer.store.chainCopy, maxGenerationChainBytes)
	if err == nil {
		durable, err := bootstrap.DecodeMaterialGenerationChain(durableWire)
		if err != nil {
			return nil, err
		}
		if len(held) == 0 || bootstrap.ExtendsMaterialGenerationChain(durable, held) {
			held = durable
		} else if !chainIs(held, durableWire) && !bootstrap.ExtendsMaterialGenerationChain(held, durable) {
			return nil, fmt.Errorf("%w: installed chain differs from durable chain", ErrMaterial)
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	staged, err := installer.stagedGenerations()
	if err != nil {
		return nil, err
	}
	if len(staged) != 0 {
		if len(held) == 0 || bootstrap.ExtendsMaterialGenerationChain(staged, held) {
			held = staged
		} else {
			wire, err := bootstrap.EncodeMaterialGenerationChain(staged)
			if err != nil || !chainIs(held, wire) {
				return nil, fmt.Errorf("%w: committed stage differs from held chain", ErrMaterial)
			}
		}
	}
	if len(held) != 0 {
		if _, err := installer.target.VerifyAdoptedChain(held, installer.historicalRoots); err != nil {
			return nil, err
		}
	}
	return held, nil
}

func (installer generationInstaller) stagedGenerations() ([]trust.Envelope, error) {
	dir, err := openMaterialDirectory(installer.store.installedDirectory, installer.store.serviceUID,
		installer.store.serviceGID, 0o700, installer.store.allowUnsafeAncestors)
	if err != nil {
		return nil, err
	}
	defer unix.Close(dir)
	staging, err := installer.store.openStaging(dir)
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	defer unix.Close(staging)
	wire, err := installer.store.readStaged(staging, MaterialGenerationsFile, "", maxGenerationChainBytes)
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return bootstrap.DecodeMaterialGenerationChain(wire)
}

func (installer generationInstaller) preserveConfig(held []trust.Envelope) error {
	if len(held) != 0 {
		verified, err := installer.target.VerifyAdoptedChain(held, installer.historicalRoots)
		if err != nil {
			return err
		}
		_, pending, err := generationConfig(installer.target, verified[len(verified)-1].Generation(), installer.config)
		if err != nil {
			return err
		}
		if pending {
			if err := os.Rename(filepath.Join(filepath.Dir(installer.config), pendingControllerConfig), installer.config); err != nil {
				return err
			}
			if err := syncDirectory(filepath.Dir(installer.config)); err != nil {
				return err
			}
		}
	}
	return nil
}

func generationConfig(target GenerationTarget, generation bootstrap.MaterialGeneration, configPath string) ([]byte, bool, error) {
	for _, pin := range generation.ControllerConfigs {
		if pin.Slot != target.Slot {
			continue
		}
		if pin.AcceptanceSHA256 != target.AcceptanceSHA256 {
			return nil, false, ErrMaterial
		}
		matches := func(wire []byte) bool { return int64(len(wire)) == pin.Size && digest(wire) == pin.SHA256 }
		if current, err := readBoundedFile(configPath, bootstrap.MaxControllerConfigBytes); err == nil && matches(current) {
			return current, false, nil
		}
		pending, err := readBoundedFile(filepath.Join(filepath.Dir(configPath), pendingControllerConfig), bootstrap.MaxControllerConfigBytes)
		if err != nil || !matches(pending) {
			return nil, false, fmt.Errorf("%w: controller config differs and no pending copy matches", ErrMaterial)
		}
		return pending, true, nil
	}
	current, err := readBoundedFile(configPath, bootstrap.MaxControllerConfigBytes)
	if err != nil || digest(current) != target.ControllerConfigSHA256 {
		return nil, false, fmt.Errorf("%w: controller config differs from accepted baseline", ErrMaterial)
	}
	return nil, false, nil
}

func materialReader(files map[string][]byte) func(string) ([]byte, error) {
	return func(name string) ([]byte, error) {
		if wire, ok := files[name]; ok {
			return wire, nil
		}
		return nil, fs.ErrNotExist
	}
}

// armedStage reads the spool's armed stage and verifies all of it again: a
// chain that extends the installed one under the current roots, armed for
// its newest generation, the slot's config for its accepted manifest, and
// every file the slot holds by pin and by CheckGenerationFiles. It returns
// no wire when nothing is armed or the stage is already installed.
func (installer generationInstaller) armedStage(held []trust.Envelope, now time.Time,
) ([]byte, []trust.Envelope, map[string][]byte, []byte, error) {
	spool, err := os.OpenRoot(installer.spool)
	if errors.Is(err, fs.ErrNotExist) {
		return nil, nil, nil, nil, nil
	}
	if err != nil {
		return nil, nil, nil, nil, err
	}
	defer spool.Close()
	armed, err := readSpooled(spool, GenerationArmedFile, 128)
	if errors.Is(err, fs.ErrNotExist) {
		return nil, nil, nil, nil, nil
	}
	if err != nil {
		return nil, nil, nil, nil, err
	}
	wire, err := readSpooled(spool, MaterialGenerationsFile, maxGenerationChainBytes)
	if err != nil {
		return nil, nil, nil, nil, err
	}
	chain, err := bootstrap.DecodeMaterialGenerationChain(wire)
	if err != nil {
		return nil, nil, nil, nil, err
	}
	verified, err := installer.target.VerifyChain(chain, installer.roots, now)
	if err != nil {
		return nil, nil, nil, nil, err
	}
	newest := verified[len(verified)-1]
	if strings.TrimSpace(string(armed)) != newest.Fingerprint() {
		return nil, nil, nil, nil, errors.New("the slot is armed for another generation")
	}
	if chainIs(held, wire) {
		return nil, nil, nil, nil, nil
	}
	if !bootstrap.ExtendsMaterialGenerationChain(chain, held) {
		return nil, nil, nil, nil, errors.New("the staged chain does not extend the installed generations")
	}
	slot := installer.target.Slot
	generation := newest.Generation()
	files := map[string][]byte{}
	for _, secret := range generation.Secrets {
		if secret.Slot != "" && secret.Slot != slot {
			continue
		}
		if files[secret.TargetFile], err = readSpooled(spool, secret.TargetFile, secret.MaxBytes); err != nil {
			return nil, nil, nil, nil, err
		}
	}
	var config []byte
	if index := slices.IndexFunc(generation.ControllerConfigs, func(pin bootstrap.GenerationControllerConfig) bool {
		return pin.Slot == slot
	}); index >= 0 {
		if generation.ControllerConfigs[index].AcceptanceSHA256 != installer.target.AcceptanceSHA256 {
			return nil, nil, nil, nil, errors.New("the generation's config is for another acceptance of this slot")
		}
		if config, err = readSpooled(spool, GenerationConfigFile(slot), bootstrap.MaxControllerConfigBytes); err != nil {
			return nil, nil, nil, nil, err
		}
	}
	if err := installer.target.VerifyFiles(generation, func(name string) ([]byte, error) {
		if data, ok := files[name]; ok {
			return data, nil
		}
		if config != nil && name == GenerationConfigFile(slot) {
			return config, nil
		}
		return nil, fs.ErrNotExist
	}, now); err != nil {
		clearContents(files)
		return nil, nil, nil, nil, err
	}
	return wire, chain, files, config, nil
}

func writeSynced(path string, data []byte) error {
	file, err := os.CreateTemp(filepath.Dir(path), ".generation-config-")
	if err != nil {
		return err
	}
	defer os.Remove(file.Name())
	defer file.Close()
	if err := file.Chmod(0o644); err != nil {
		return err
	}
	if _, err := file.Write(data); err != nil {
		return err
	}
	if err := file.Sync(); err != nil {
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := os.Rename(file.Name(), path); err != nil {
		return err
	}
	return syncDirectory(filepath.Dir(path))
}

func syncDirectory(path string) error {
	dir, err := os.Open(path)
	if err != nil {
		return err
	}
	defer dir.Close()
	return dir.Sync()
}

func materialReferences(accepted AcceptedIdentity, newest *bootstrap.VerifiedMaterialGeneration) map[string]bootstrap.SecretReference {
	refs := map[string]bootstrap.SecretReference{}
	for _, reference := range accepted.MaterialReferences {
		refs[reference.TargetFile] = reference
	}
	if newest != nil {
		for _, secret := range newest.Generation().Secrets {
			if secret.Slot == "" || secret.Slot == accepted.Slot {
				refs[secret.TargetFile] = secret
			}
		}
	}
	return refs
}

func readReferences(ctx context.Context, refs map[string]bootstrap.SecretReference, read SecretReader) (map[string][]byte, error) {
	if read == nil && len(refs) != 0 {
		return nil, ErrMaterial
	}
	contents := map[string][]byte{}
	for _, name := range slices.Sorted(maps.Keys(refs)) {
		reference := refs[name]
		if !markerNameRE.MatchString(name) {
			clearContents(contents)
			return nil, ErrMaterial
		}
		content, err := read(ctx, reference)
		if err == nil && (len(content) == 0 || int64(len(content)) > reference.MaxBytes || digest(content) != reference.SHA256) {
			clear(content)
			err = bootstrap.ErrVaultSecretMismatch
		}
		if err != nil {
			clearContents(contents)
			return nil, fmt.Errorf("read %s from Vault: %w", name, err)
		}
		contents[name] = content
	}
	return contents, nil
}

func clearContents(contents map[string][]byte) {
	for _, content := range contents {
		clear(content)
	}
}

// checkRestore reads every pin from Vault and compares it with the installed
// file, which may still be on disk. It writes nothing.
func (store MaterialStore) checkRestore(ctx context.Context, refs map[string]bootstrap.SecretReference, chain []byte,
	read SecretReader,
) (string, error) {
	contents, err := readReferences(ctx, refs, read)
	if err != nil {
		return "", err
	}
	defer clearContents(contents)
	dir, err := openMaterialDirectory(store.installedDirectory, store.serviceUID, store.serviceGID, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return "", err
	}
	defer unix.Close(dir)
	for name, content := range contents {
		installed, err := readMaterial(dir, name, store.serviceUID, store.serviceGID, digest(content), bootstrap.MaxSecretBytes)
		clear(installed)
		if err != nil {
			return "", fmt.Errorf("installed %s differs from its Vault version: %w", name, err)
		}
	}
	if chain != nil {
		installed, err := readUnpinned(dir, MaterialGenerationsFile, store.serviceUID, store.serviceGID, maxGenerationChainBytes)
		if err != nil || !bytes.Equal(installed, chain) {
			return "", fmt.Errorf("%w: installed generation chain differs from its durable copy", ErrMaterial)
		}
	}
	return fmt.Sprintf("all %d files equal their Vault versions", len(contents)), nil
}

// removeDiskCopies deletes the on-disk directory's files after each one is
// shown to equal its Vault copy (or the chain's durable copy). Anything else
// in the directory refuses the removal, so nothing unrecovered is lost.
func (store MaterialStore) removeDiskCopies(contents map[string][]byte, chain []byte) (int, error) {
	dir, err := openMaterialDirectory(store.installedDirectory, store.serviceUID, store.serviceGID, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return 0, err
	}
	defer unix.Close(dir)
	names, err := stagedNames(dir)
	if err != nil {
		return 0, err
	}
	for _, name := range names {
		var installed []byte
		if want, ok := contents[name]; ok {
			installed, err = readMaterial(dir, name, store.serviceUID, store.serviceGID, digest(want), bootstrap.MaxSecretBytes)
		} else if name == MaterialGenerationsFile && chain != nil {
			installed, err = readUnpinned(dir, name, store.serviceUID, store.serviceGID, maxGenerationChainBytes)
			if err == nil && !bytes.Equal(installed, chain) {
				err = ErrMaterial
			}
		} else {
			err = fmt.Errorf("%w: %s has no Vault copy", ErrMaterial, name)
		}
		clear(installed)
		if err != nil {
			return 0, fmt.Errorf("keep the disk copies: %s: %w", name, err)
		}
	}
	// Keep the predecessor chain until its last secret is gone so cleanup can retry.
	if index := slices.Index(names, MaterialGenerationsFile); index >= 0 {
		names = append(slices.Delete(names, index, index+1), MaterialGenerationsFile)
	}
	for _, name := range names {
		if err := unix.Unlinkat(dir, name, 0); err != nil {
			return 0, fmt.Errorf("remove disk copy %s: %w", name, err)
		}
	}
	return len(names), unix.Fsync(dir)
}

func (store MaterialStore) fill(contents map[string][]byte, chain []byte) error {
	dir, err := openMaterialDirectory(store.installedDirectory, store.serviceUID, store.serviceGID, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return err
	}
	defer unix.Close(dir)
	for _, name := range slices.Sorted(maps.Keys(contents)) {
		if err := store.installMaterial(dir, name, contents[name], digest(contents[name]), bootstrap.MaxSecretBytes); err != nil {
			return fmt.Errorf("install %s: %w", name, err)
		}
	}
	if chain == nil {
		return nil
	}
	installed, err := readUnpinned(dir, MaterialGenerationsFile, store.serviceUID, store.serviceGID, maxGenerationChainBytes)
	if errors.Is(err, os.ErrNotExist) {
		return store.writeStaged(dir, MaterialGenerationsFile, chain)
	}
	if err == nil && !bytes.Equal(installed, chain) {
		err = fmt.Errorf("%w: installed generation chain differs from its durable copy", ErrMaterial)
	}
	return err
}

// keepChain writes the durable copy of a staged chain before it commits.
func (store MaterialStore) keepChain(staging int) error {
	if store.chainCopy == "" {
		return nil
	}
	chain, err := readUnpinned(staging, MaterialGenerationsFile, store.serviceUID, store.serviceGID, maxGenerationChainBytes)
	if err != nil {
		return err
	}
	return writeSynced(store.chainCopy, chain)
}

func memoryFilesystem(fd int) bool {
	var fs unix.Statfs_t
	return unix.Fstatfs(fd, &fs) == nil && fs.Type == unix.TMPFS_MAGIC
}

// requireSwapOff refuses to put credentials in memory that could be paged to
// disk, also into a tmpfs mounted earlier.
func requireSwapOff() error {
	if !vaultsecret.SwapOff() {
		return errors.New("controller credentials need swap disabled")
	}
	return nil
}

// mountMemory mounts an owner-only tmpfs at path. It keeps tmpfs's default
// cap, half the RAM: a legal manifest and generation may pin hundreds of
// files of up to bootstrap.MaxSecretBytes, and an adoption stages a whole set
// beside them, so a smaller fixed cap could fail a restore after its disk
// copies are gone. tmpfs holds only what is written.
func mountMemory(path string, uid, gid uint32) error {
	if filepath.Clean(path) != path {
		return ErrMaterial
	}
	return unix.Mount("tmpfs", path, "tmpfs", unix.MS_NOSUID|unix.MS_NODEV|unix.MS_NOEXEC,
		fmt.Sprintf("mode=0700,uid=%d,gid=%d", uid, gid))
}

func verifyRestoreContents(target GenerationTarget, roots trust.Keyring, chainWire []byte, contents map[string][]byte, configPath string, now time.Time) error {
	if chainWire == nil {
		config, err := readBoundedFile(configPath, bootstrap.MaxControllerConfigBytes)
		if err != nil || digest(config) != target.ControllerConfigSHA256 {
			return fmt.Errorf("%w: controller config differs from accepted baseline", ErrMaterial)
		}
		return nil
	}
	chain, err := bootstrap.DecodeMaterialGenerationChain(chainWire)
	if err != nil {
		return err
	}
	verified, err := target.VerifyAdoptedChain(chain, roots)
	if err != nil {
		return err
	}
	newest := verified[len(verified)-1]
	if !now.Before(newest.ExpiresAt()) {
		return fmt.Errorf("%w: adopted material generation expired", ErrMaterial)
	}
	config, _, err := generationConfig(target, newest.Generation(), configPath)
	if err != nil {
		return err
	}
	files := maps.Clone(contents)
	if config != nil {
		files[GenerationConfigFile(target.Slot)] = config
	}
	return target.VerifyFiles(newest.Generation(), materialReader(files), now)
}

func convergeRestoredConfig(store MaterialStore, target GenerationTarget, roots trust.Keyring, chainWire []byte, configPath string, now time.Time, contents map[string][]byte) error {
	if err := verifyRestoreContents(target, roots, chainWire, contents, configPath, now); err != nil {
		return err
	}
	chain, err := bootstrap.DecodeMaterialGenerationChain(chainWire)
	if err != nil {
		return err
	}
	generation, err := bootstrap.MaterialGenerationPayload(chain[len(chain)-1])
	if err != nil {
		return err
	}
	_, pending, err := generationConfig(target, generation, configPath)
	if err != nil || !pending {
		return err
	}
	if err := os.Rename(filepath.Join(filepath.Dir(configPath), pendingControllerConfig), configPath); err != nil {
		return err
	}
	return syncDirectory(filepath.Dir(configPath))
}

func (store MaterialStore) verifyInstalled(ctx context.Context, dir int, expected map[string]string) error {
	for name, want := range expected {
		if err := ctx.Err(); err != nil {
			return err
		}
		content, err := readMaterial(dir, name, store.serviceUID, store.serviceGID, want, bootstrap.MaxSecretBytes)
		if err != nil {
			return fmt.Errorf("verify installed secret %s: %w", name, err)
		}
		clear(content)
	}
	return nil
}

func sameMaterials(left, right map[string]string) bool {
	if len(left) == 0 || len(left) != len(right) {
		return false
	}
	for name, digest := range left {
		if right[name] != digest {
			return false
		}
	}
	return true
}

func (store MaterialStore) installMaterial(dir int, name string, content []byte, want string, maximum int64) error {
	if existing, err := readMaterial(dir, name, store.serviceUID, store.serviceGID, want, maximum); err == nil {
		clear(existing)
		return nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return err
	}
	var nonce [12]byte
	if _, err := rand.Read(nonce[:]); err != nil {
		return err
	}
	temporary := ".secret-" + hex.EncodeToString(nonce[:])
	fd, err := unix.Openat(dir, temporary, unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0o600)
	if err != nil {
		return err
	}
	defer unix.Unlinkat(dir, temporary, 0)
	file := os.NewFile(uintptr(fd), temporary)
	if err := unix.Fchmod(fd, 0o600); err != nil {
		_ = file.Close()
		return err
	}
	if err := unix.Fchown(fd, int(store.serviceUID), int(store.serviceGID)); err != nil {
		_ = file.Close()
		return err
	}
	if n, err := file.Write(content); err != nil || n != len(content) {
		_ = file.Close()
		return errors.Join(err, io.ErrShortWrite)
	}
	if err := file.Sync(); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := unix.Renameat2(dir, temporary, dir, name, unix.RENAME_NOREPLACE); err != nil {
		if !errors.Is(err, unix.EEXIST) {
			return err
		}
	}
	if err := unix.Fsync(dir); err != nil {
		return err
	}
	verified, err := readMaterial(dir, name, store.serviceUID, store.serviceGID, want, maximum)
	clear(verified)
	return err
}

func readMaterial(dir int, name string, uid, gid uint32, want string, maximum int64) ([]byte, error) {
	if !markerNameRE.MatchString(name) || !markerDigestRE.MatchString(want) || maximum <= 0 || maximum > bootstrap.MaxSecretBytes {
		return nil, ErrMaterial
	}
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != 0o600 || stat.Nlink != 1 ||
		stat.Size <= 0 || stat.Size > maximum {
		return nil, ErrMaterial
	}
	content, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil || len(content) == 0 || int64(len(content)) > maximum || digest(content) != want {
		clear(content)
		return nil, ErrMaterial
	}
	return content, nil
}

func openMaterialDirectory(path string, uid, gid uint32, mode uint32, allowUnsafeAncestors bool) (int, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return -1, ErrMaterial
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	components := strings.Split(strings.TrimPrefix(path, "/"), "/")
	for index, component := range components {
		if component == "" || component == "." || component == ".." {
			unix.Close(fd)
			return -1, ErrMaterial
		}
		next, err := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
		unix.Close(fd)
		if err != nil {
			return -1, err
		}
		fd = next
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil ||
			index < len(components)-1 && !allowUnsafeAncestors && (stat.Uid != 0 || stat.Mode&0o022 != 0) {
			unix.Close(fd)
			return -1, ErrMaterial
		}
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != mode {
		unix.Close(fd)
		return -1, ErrMaterial
	}
	return fd, nil
}

func readUnpinned(dir int, name string, uid, gid uint32, maximum int64) ([]byte, error) {
	if !markerNameRE.MatchString(name) || maximum <= 0 {
		return nil, ErrMaterial
	}
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != 0o600 || stat.Nlink != 1 ||
		stat.Size <= 0 || stat.Size > maximum {
		return nil, ErrMaterial
	}
	content, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil || len(content) == 0 || int64(len(content)) > maximum {
		clear(content)
		return nil, ErrMaterial
	}
	return content, nil
}

func generationTarget(accepted AcceptedIdentity) (GenerationTarget, error) {
	acceptance, err := accepted.AcceptanceSHA256()
	if err != nil {
		return GenerationTarget{}, err
	}
	return GenerationTarget{Slot: accepted.Slot, AcceptanceSHA256: acceptance, Broker: accepted.Broker,
		MaterialGenerationSHA256: accepted.MaterialGenerationSHA256, ControllerConfigSHA256: accepted.ConfigSHA256["controller.json"],
		Expected: bootstrap.MaterialGenerationExpectation{DeploymentID: accepted.DeploymentID,
			Environment: accepted.Environment, ClusterID: accepted.ClusterID, Cell: oci.Region(accepted.Cell),
			ControllerSlots: slices.Clone(accepted.ControllerSlots)}}, nil
}

// VerifyChain admits a new or interrupted generation under the current roots.
func (target GenerationTarget) VerifyChain(chain []trust.Envelope, roots trust.Keyring, now time.Time) ([]bootstrap.VerifiedMaterialGeneration, error) {
	verified, err := bootstrap.VerifyMaterialGenerationChain(chain, roots, target.Expected, now)
	if err != nil {
		return nil, err
	}
	return target.bindChain(verified)
}

// VerifyAdoptedChain verifies a previously installed chain's signatures and acceptance.
func (target GenerationTarget) VerifyAdoptedChain(chain []trust.Envelope, roots trust.Keyring) ([]bootstrap.VerifiedMaterialGeneration, error) {
	verified, err := bootstrap.VerifyAdoptedMaterialGenerationChain(chain, roots, target.Expected)
	if err != nil {
		return nil, err
	}
	return target.bindChain(verified)
}

func (target GenerationTarget) bindChain(verified []bootstrap.VerifiedMaterialGeneration) ([]bootstrap.VerifiedMaterialGeneration, error) {
	if !slices.Contains(target.Expected.ControllerSlots, target.Slot) || !markerDigestRE.MatchString(target.AcceptanceSHA256) ||
		validateAcceptedBroker(target.Broker) != nil || len(verified) == 0 {
		return nil, ErrMaterial
	}
	baseline := target.MaterialGenerationSHA256 == ""
	for _, item := range verified {
		generation := item.Generation()
		if generation.Operator != target.Broker.Operator || generation.SystemAccount != target.Broker.SystemAccount ||
			generation.CellAccount != target.Broker.CellAccount || generation.HostSigner != target.Broker.HostSigner ||
			generation.RoleSigner != target.Broker.RoleSigner {
			return nil, fmt.Errorf("%w: generation changes the accepted broker identity", ErrMaterial)
		}
		if item.Fingerprint() == target.MaterialGenerationSHA256 {
			baseline = true
			if generation.AccountSigner != target.Broker.AccountSigner {
				return nil, fmt.Errorf("%w: accepted generation changes the account signer", ErrMaterial)
			}
		}
	}
	if !baseline {
		return nil, fmt.Errorf("%w: chain omits the accepted material generation", ErrMaterial)
	}
	for _, pin := range verified[len(verified)-1].Generation().ControllerConfigs {
		if pin.Slot == target.Slot && pin.AcceptanceSHA256 != target.AcceptanceSHA256 {
			return nil, fmt.Errorf("%w: generation config is bound to another acceptance", ErrMaterial)
		}
	}
	return verified, nil
}

// VerifyFiles checks every local file and config, plus their material semantics.
func (target GenerationTarget) VerifyFiles(generation bootstrap.MaterialGeneration, read func(string) ([]byte, error), now time.Time) error {
	for _, secret := range generation.Secrets {
		if secret.Slot == "" || secret.Slot == target.Slot {
			if _, err := read(secret.TargetFile); err != nil {
				return err
			}
		}
	}
	for _, pin := range generation.ControllerConfigs {
		if pin.Slot == target.Slot {
			if pin.AcceptanceSHA256 != target.AcceptanceSHA256 {
				return fmt.Errorf("%w: controller config is bound to another acceptance", ErrMaterial)
			}
			if _, err := read(GenerationConfigFile(target.Slot)); err != nil {
				return err
			}
		}
	}
	if _, err := bootstrapmaterial.CheckGenerationFiles(generation, read, now); err != nil {
		return err
	}
	if target.Broker.InterRegionAccount != "" {
		wire, err := read("interregion.jwt")
		if err != nil {
			return err
		}
		claim, err := jwt.DecodeAccountClaims(strings.TrimSpace(string(wire)))
		if err != nil || claim.Subject != target.Broker.InterRegionAccount {
			return fmt.Errorf("%w: interregion account differs from accepted broker", ErrMaterial)
		}
	}
	return nil
}

